class ScottNav extends HTMLElement{connectedCallback(){const n=window.location.pathname.replace(/index\.html$/,"").replace(/\/$/,"")||"/",e=this.getAttribute("skip-target")||"#main-content";if(!document.getElementById("scott-nav-style")){const n=document.createElement("style");n.id="scott-nav-style",n.textContent='\n        .sl-skip-link {\n          position: absolute;\n          left: -9999px;\n          top: 0;\n          background: #1e3a5f;\n          color: #fff;\n          padding: 0.85rem 1.25rem;\n          font-size: 1rem;\n          font-weight: 600;\n          z-index: 1000;\n          border-radius: 0 0 6px 0;\n        }\n        .sl-skip-link:focus {\n          left: 0;\n        }\n\n        .sl-nav {\n          position: sticky;\n          top: 0;\n          z-index: 500;\n          background: var(--bg-color, #ffffff);\n          border-bottom: 1px solid var(--border-color, #e5e5e5);\n        }\n\n        .sl-nav-inner {\n          display: flex;\n          align-items: center;\n          gap: 1.5rem;\n          max-width: 1200px;\n          margin: 0 auto;\n          padding: 0 1rem;\n        }\n\n        .sl-nav-brand {\n          display: flex;\n          align-items: center;\n          gap: 0.5rem;\n          flex-shrink: 0;\n          padding: 0.75rem 0;\n          border-bottom: none !important;\n          color: var(--text-color, #111111);\n          text-decoration: none;\n          font-weight: 700;\n          font-size: 1.05rem;\n        }\n        .sl-nav-brand img {\n          display: block;\n          height: 30px;\n          width: auto;\n        }\n\n        .sl-nav-bars {\n          display: flex;\n          align-items: flex-end;\n          gap: 0.25rem;\n          list-style: none;\n          margin: 0;\n          padding: 0.25rem 0 0 0;\n          overflow-x: auto;\n          scroll-snap-type: x proximity;\n          -webkit-overflow-scrolling: touch;\n        }\n        .sl-nav-bars::-webkit-scrollbar {\n          height: 5px;\n        }\n        .sl-nav-bars::-webkit-scrollbar-thumb {\n          background: var(--border-color, #e5e5e5);\n          border-radius: 4px;\n        }\n\n        .sl-bar-item {\n          scroll-snap-align: start;\n        }\n\n        .sl-bar {\n          display: flex;\n          flex-direction: column;\n          align-items: center;\n          justify-content: flex-end;\n          gap: 0.4rem;\n          width: 78px;\n          min-height: 68px;\n          padding: 0.4rem 0.25rem 0.6rem;\n          text-decoration: none;\n          border-radius: 6px;\n          border: 2px solid transparent;\n        }\n        .sl-bar:hover,\n        .sl-bar:focus-visible {\n          border-color: #1e3a5f;\n        }\n        .sl-bar:focus-visible {\n          outline: 3px solid #1e3a5f;\n          outline-offset: 2px;\n        }\n\n        .sl-bar-fill {\n          width: 30px;\n          border-radius: 3px 3px 0 0;\n          background: #eef2f6;\n          border-top: 3px solid #1e3a5f;\n          position: relative;\n        }\n        @media (prefers-reduced-motion: no-preference) {\n          .sl-bar-fill {\n            transition: height 0.15s ease, background-color 0.15s ease;\n          }\n        }\n        .sl-bar:hover .sl-bar-fill,\n        .sl-bar:focus-visible .sl-bar-fill {\n          background: #dbe4ec;\n        }\n\n        .sl-bar-label {\n          font-size: 0.95rem;\n          font-weight: 500;\n          color: var(--text-color, #111111);\n          white-space: nowrap;\n        }\n\n        /* Current page: tallest, filled solid, dot marker, bold label -\n           three signals beyond color, per WCAG 1.4.1. */\n        .sl-bar[aria-current="page"] .sl-bar-fill {\n          background: #1e3a5f;\n          height: 66px !important;\n        }\n        .sl-bar[aria-current="page"] .sl-bar-fill::after {\n          content: "";\n          position: absolute;\n          top: -7px;\n          left: 50%;\n          transform: translateX(-50%);\n          width: 9px;\n          height: 9px;\n          border-radius: 50%;\n          background: #1e3a5f;\n        }\n        .sl-bar[aria-current="page"] .sl-bar-label {\n          font-weight: 700;\n          color: #1e3a5f;\n          text-decoration: underline;\n          text-underline-offset: 3px;\n        }\n\n        @media screen and (max-width: 736px) {\n          .sl-nav-brand span {\n            display: none;\n          }\n        }\n      ',document.head.appendChild(n)}const a=[{href:"/index.html",label:"Home",height:26},{href:"/services.html",label:"Services",height:34},{href:"/case-studies.html",label:"Work",height:42},{href:"/insights.html",label:"Insights",height:50},{href:"/about.html",label:"About",height:58},{href:"/contact.html",label:"Contact",height:66}].map(e=>{const a=(e.href.replace(/index\.html$/,"").replace(/\/$/,"")||"/")===n;return`\n          <li class="sl-bar-item">\n            <a\n              href="${e.href}"\n              class="sl-bar"\n              ${a?'aria-current="page"':""}\n            >\n              <span class="sl-bar-fill" style="height:${e.height}px;"></span>\n              <span class="sl-bar-label">${e.label}</span>\n            </a>\n          </li>\n        `}).join("");this.innerHTML=`\n      <a href="${e}" class="sl-skip-link">Skip to main content</a>\n\n      <nav class="sl-nav" aria-label="Primary">\n        <div class="sl-nav-inner">\n          <a href="/index.html" class="sl-nav-brand">\n            <img src="/images/scottlabz-clear.webp" alt="" width="30" height="39" />\n            <span>Scott Labz</span>\n          </a>\n\n          <ul class="sl-nav-bars" role="list">\n            ${a}\n          </ul>\n        </div>\n      </nav>\n    `}}customElements.define("scott-nav",ScottNav);